const fs = require('fs');
const payloads = {"shared/interfaces/campaign.ts": "", "src/main/ipc/register-campaign-ipc.ts": "", "src/renderer/pages/CampaignPage.tsx": ""};
for (const [file, encoded] of Object.entries(payloads)) {
  if (!fs.existsSync(file)) throw new Error(`Dosya bulunamadı: ${file}`);
  fs.copyFileSync(file, `${file}.before-package-11-v2.bak`);
  fs.writeFileSync(file, Buffer.from(encoded, 'base64').toString('utf8'), 'utf8');
  console.log(`Guncellendi: ${file}`);
}
